uv run python -c "import numpy as np, pandas as pd; train=pd.read_csv('train.csv'); X=train.drop(columns=['target']).to_numpy(float); y=train['target'].to_numpy(float); parts=np.array_split(np.arange(len(y)),5); rmse=lambda a,b: float(np.sqrt(np.mean((a-b)**2)));

def fit_ols(Xtr,ytr):
    X1=np.column_stack([np.ones(len(Xtr)),Xtr]); return np.linalg.lstsq(X1,ytr,rcond=None)[0]

def pred_ols(c,Xte):
    return np.column_stack([np.ones(len(Xte)),Xte])@c

def fit_ridge(Xtr,ytr,alpha):
    xm=Xtr.mean(0); xs=Xtr.std(0); xs[xs==0]=1.0; Z=(Xtr-xm)/xs; ym=ytr.mean(); yc=ytr-ym; w=np.linalg.solve(Z.T@Z + alpha*np.eye(Z.shape[1]), Z.T@yc); return xm,xs,ym,w

def pred_ridge(m,Xte):
    xm,xs,ym,w=m; return ym + ((Xte-xm)/xs)@w

for name in ['mean','ols']:
    scores=[]
    for i in range(5):
        te=parts[i]; tr=np.concatenate([parts[j] for j in range(5) if j!=i]); Xtr,ytr=X[tr],y[tr]; Xte,yte=X[te],y[te]; pred=np.full(len(te), ytr.mean()) if name=='mean' else pred_ols(fit_ols(Xtr,ytr), Xte); scores.append(rmse(yte,pred))
    print(name, round(float(np.mean(scores)), 6))
for alpha in [1e-4,1e-3,1e-2,1e-1,1.0,10.0,100.0,1000.0]:
    scores=[]
    for i in range(5):
        te=parts[i]; tr=np.concatenate([parts[j] for j in range(5) if j!=i]); Xtr,ytr=X[tr],y[tr]; Xte,yte=X[te],y[te]; pred=pred_ridge(fit_ridge(Xtr,ytr,alpha), Xte); scores.append(rmse(yte,pred))
    print('ridge', alpha, round(float(np.mean(scores)), 6))"
